const fs=require('fs'),vm=require('vm'),assert=require('assert/strict');const s=fs.readFileSync('xiaola-chat.js','utf8'),start=s.indexOf('/* Chat experience:');assert(start>0);const ctx={};vm.createContext(ctx);vm.runInContext(s.slice(0,start),ctx);const q=ctx.qrcode(0,'M');q.addData('https://q.lakala.com/r/demo?x=1');q.make();assert.ok(q.createDataURL(4,16).startsWith('data:image/gif;base64,'));const html=fs.readFileSync('xiaola-widget.html','utf8');assert(!html.includes('src="vendor/qrcode-generator'));assert(html.includes('xiaola-chat.js?v=23'));console.log('widget chat contains browser QR library without separate asset request');
